// ratelimit.go
package ratelimit

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by time.Now.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu        sync.Mutex
	rate      float64   // tokens per second
	burst     float64   // bucket capacity
	tokens    float64   // current tokens
	last      time.Time // last refill time
	clock     Clock
	nowFn     func() time.Time // for deterministic tests
}

var ErrInvalidConfig = errors.New("ratelimit: invalid configuration")

// New creates a Limiter with the given refill rate (tokens/sec) and burst
// capacity. The bucket starts full.
func New(rate, burst float64, opts ...Option) (*Limiter, error) {
	if rate <= 0 {
		return nil, fmt.Errorf("%w: rate must be > 0, got %v", ErrInvalidConfig, rate)
	}
	if burst <= 0 {
		return nil, fmt.Errorf("%w: burst must be > 0, got %v", ErrInvalidConfig, burst)
	}
	l := &Limiter{
		rate:  rate,
		burst: burst,
		tokens: burst,
		clock: RealClock(),
	}
	for _, o := range opts {
		o(l)
	}
	l.last = l.clock.Now()
	return l, nil
}

// Option configures a Limiter.
type Option func(*Limiter)

// WithClock injects a custom Clock.
func WithClock(c Clock) Option {
	return func(l *Limiter) { l.clock = c }
}

// refill advances the bucket to time t, adding accrued tokens.
func (l *Limiter) refill(t time.Time) {
	elapsed := t.Sub(l.last)
	if elapsed <= 0 {
		return
	}
	l.tokens += elapsed.Seconds() * l.rate
	if l.tokens > l.burst {
		l.tokens = l.burst
	}
	l.last = t
}

// AllowN reports whether n tokens may be consumed at time now,
// consuming them if so.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(now)
	need := float64(n)
	if l.tokens >= need {
		l.tokens -= need
		return true
	}
	return false
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// Tokens returns the current number of available tokens (for observability).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(l.clock.Now())
	return l.tokens
}
