// ratelimit_test.go
package ratelimit

import (
	"errors"
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	t time.Time
}

func (f *fakeClock) Now() time.Time { return f.t }
func (f *fakeClock) Advance(d time.Duration) {
	f.t = f.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	cases := []struct {
		name  string
		rate  float64
		burst float64
		want  error
	}{
		{"ok", 1, 1, nil},
		{"zero rate", 0, 1, ErrInvalidConfig},
		{"negative rate", -1, 1, ErrInvalidConfig},
		{"zero burst", 1, 0, ErrInvalidConfig},
		{"negative burst", 1, -5, ErrInvalidConfig},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			_, err := New(tc.rate, tc.burst)
			if !errors.Is(err, tc.want) {
				t.Fatalf("New(%v,%v) error = %v, want %v", tc.rate, tc.burst, err, tc.want)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)
	cases := []struct {
		name  string
		rate  float64
		burst float64
		steps []struct {
			advance time.Duration
			n       int
			want    bool
		}
	}{
		{
			name: "burst exhausted then refill",
			rate: 1, burst: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},
				{0, 1, false},
				{time.Second, 1, true},
				{0, 1, false},
			},
		},
		{
			name: "partial refill accumulates",
			rate: 2, burst: 3,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 3, true},
				{250 * time.Millisecond, 1, false}, // 0.5 tokens
				{250 * time.Millisecond, 1, true},  // 1.0 tokens
				{0, 1, false},
			},
		},
		{
			name: "cannot exceed burst",
			rate: 10, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{10 * time.Second, 2, false},
				{0, 1, true},
			},
		},
		{
			name: "negative n denied",
			rate: 1, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, -1, false},
				{0, 1, true},
			},
		},
		{
			name: "zero n allowed without effect",
			rate: 1, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 0, true},
				{0, 1, true},
				{0, 1, false},
			},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			fc := &fakeClock{t: base}
			l, err := New(tc.rate, tc.burst, WithClock(fc))
			if err != nil {
				t.Fatalf("New: %v", err)
			}
			for i, s := range tc.steps {
				fc.Advance(s.advance)
				if got := l.AllowN(fc.Now(), s.n); got != s.want {
					t.Fatalf("step %d: AllowN(%v) = %v, want %v", i, s.n, got, s.want)
				}
			}
		})
	}
}

func TestConcurrentAccess(t *testing.T) {
	fc := &fakeClock{t: time.Now()}
	l, err := New(1000, 100, WithClock(fc))
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	var wg sync.WaitGroup
	var allowed int64
	var mu sync.Mutex
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if l.AllowN(fc.Now(), 1) {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if allowed != 100 {
		t.Fatalf("allowed = %d, want 100 (burst starts full)", allowed)
	}
	if got := l.AllowN(fc.Now(), 1); got {
		t.Fatal("expected denial after burst exhausted")
	}
}

func TestTokensRefillsUpToBurst(t *testing.T) {
	fc := &fakeClock{t: time.Now()}
	l, err := New(1, 2, WithClock(fc))
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	l.AllowN(fc.Now(), 2)
	if got := l.Tokens(); got != 0 {
		t.Fatalf("tokens = %v, want 0", got)
	}
	fc.Advance(5 * time.Second)
	if got := l.Tokens(); got != 2 {
		t.Fatalf("tokens = %v, want 2 (capped at burst)", got)
	}
}
